from typing import Any, Mapping
import re


def render_template(template: str, context: Mapping[str, Any]) -> str:
    """
    Render "{{ ... }}" placeholders in a notification/email template.
    """
    def get_value(path: str, ctx: Mapping[str, Any]) -> Any:
        parts = path.split('.')
        curr = ctx
        for part in parts:
            if isinstance(curr, Mapping):
                curr = curr[part]
            else:
                raise KeyError(f"Cannot index non-mapping type")
        return curr

    def process_match(match: re.Match) -> str:
        content = match.group(1).strip()
        parts = [p.strip() for p in content.split('|')]
        path = parts[0]
        val = get_value(path, context)

        val_str = "" if val is None else str(val)

        filters = {
            'upper': lambda s: s.upper(),
            'lower': lambda s: s.lower(),
            'title': lambda s: s.title(),
            'trim': lambda s: s.strip(),
        }

        for f_name in parts[1:]:
            if f_name not in filters:
                raise ValueError(f"Unknown filter: {f_name}")
            val_str = filters[f_name](val_str)
        return val_str

    return re.sub(r'\{\{\s*(.*?)\s*\}\}', process_match, template)"
